const src = $json.body || $json || {};
const accountId = Number(src.account_id || 2);
const baseUrl = String(src.base_url || 'http://chatwoot:3000').replace(/\/$/, '');
if (src.mode === 'list' || src.list === true) {
  return [{ json: { mode: 'list', page: Number(src.page || 1), status: String(src.status || 'open'), account_id: accountId, base_url: baseUrl } }];
}
const ids = Array.isArray(src.chatwoot_conv_ids) ? src.chatwoot_conv_ids.map(Number).filter(Boolean) : [];
if (!ids.length) throw new Error('chatwoot_conv_ids is required unless mode=list');
return ids.map(id => ({ json: { mode: 'messages', id, account_id: accountId, base_url: baseUrl } }));

const items = $input.all();
const result = [];
for (const item of items) {
  const row = item.json || {};
  const payload = Array.isArray(row.payload)
    ? row.payload
    : (Array.isArray(row.data?.payload) ? row.data.payload : (Array.isArray(row.data) ? row.data : (Array.isArray(row) ? row : [])));
  const first = payload[0] || {};
  const looksLikeMessages = Boolean(first.content_type || first.message_type || first.conversation_id || first.sender);
  if (!looksLikeMessages) {
    result.push({ json: { mode: 'list', conversation_count: payload.length, conversations: payload, meta: row.meta || row.data?.meta || {}, raw_keys: Object.keys(row), payload_type: Array.isArray(row.payload) ? 'array' : typeof row.payload } });
    continue;
  }
  const messages = payload.map(m => ({
    id: m.id,
    conversation_id: m.conversation_id,
    message_type: m.message_type,
    content_type: m.content_type,
    content: m.content,
    private: m.private,
    created_at: m.created_at,
    sender_type: m.sender_type || m.sender?.type || null,
    sender_name: m.sender?.name || m.sender?.available_name || null,
    content_attributes: m.content_attributes || {},
  }));
  result.push({ json: { mode: 'messages', conversation_id: messages[0]?.conversation_id || null, message_count: messages.length, messages } });
}
return result;
